import numpy as np
def equation(eps, T, params):
    p = params
    a = p[0] + p[1]*T + p[2]/T + p[3]/T**2 + p[4]*T**2
    c1 = p[5] + p[6]/T
    return a + c1*eps + p[7]*eps**2 + p[8]*np.log(eps) + p[9]*np.sqrt(eps)
